using Npgsql;
namespace BmsDesktop.Infrastructure;
public sealed class DocumentNumberService { private readonly Database _db; public DocumentNumberService(Database db)=>_db=db; public async Task<string> NextAsync(string type,string prefix,DateOnly date){await using var cn=await _db.OpenAsync();await using var tx=await cn.BeginTransactionAsync();await using var cmd=new NpgsqlCommand("insert into document_sequences(document_type,year,last_number) values(@t,@y,1) on conflict(document_type,year) do update set last_number=document_sequences.last_number+1 returning last_number",cn,tx);cmd.Parameters.AddWithValue("t",type);cmd.Parameters.AddWithValue("y",date.Year);var n=Convert.ToInt32(await cmd.ExecuteScalarAsync());await tx.CommitAsync();return $"{prefix}/{date:yyyy}/{n:000000}";} }
